from itertools import product

def tiles(grid):
    h,w=len(grid),len(grid[0]); cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    pieces=[]
    for r in range(h-1):
      for c in range(w-1):
        box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if box<=cells: pieces.append(('sq',box))
        for miss in box:
          p=box-{miss}
          if p<=cells: pieces.append(('L',p))
    by={x:[] for x in cells}
    for p in pieces:
      for x in p[1]: by[x].append(p)
    sols=[]
    def rec(left,chosen):
      if not left: sols.append(chosen); return
      x=min(left,key=lambda x:sum(p[1]<=left for p in by[x]))
      for p in by[x]:
        if p[1]<=left: rec(left-p[1],chosen+[p])
    rec(cells,[])
    return sols

